	if len(dirs) == 0 {
		return ""
	}
	return "libnvvm is normally installed in " + strings.Join(dirs, ", ") +
		", which the dynamic linker does not search; set NVVM_LIB_PATH to the library path, or add the directory to LD_LIBRARY_PATH"
